Two threads share mutexes A and B:

```c
/* Thread 1 */            /* Thread 2 */
lock(&A);                 lock(&B);
lock(&B);                 lock(&A);
/* critical section */    /* critical section */
unlock(&B);               unlock(&A);
unlock(&A);               unlock(&B);
```

Which change **guarantees** that these threads can never deadlock, while both still access the critical section with both locks held?

Two threads use mutexes A and B as follows. `trylock(&m)` acquires m and returns true if m is free. Otherwise it returns false immediately, without blocking.

```c
/* Thread 1 */                    /* Thread 2 */
lock(&A);                         lock(&B);
while (!trylock(&B)) {            while (!trylock(&A)) {
    unlock(&A);                       unlock(&B);
    lock(&A);                         lock(&B);
}                                 }
/* use A and B */                 /* use A and B */
unlock(&B); unlock(&A);           unlock(&A); unlock(&B);
```

Which statements are **true**?

Each account has a unique integer `id` and a non-recursive mutex `m`. Any of these functions may run concurrently in different threads, on any accounts:

```c
mutex L;                        /* protects the global log */

void transfer(Account *x, Account *y, int amt) {   /* x != y */
    Account *first  = (x->id < y->id) ? x : y;
    Account *second = (x->id < y->id) ? y : x;
    lock(&first->m);  lock(&second->m);
    x->bal -= amt;    y->bal += amt;
    lock(&L);  log_append(x, y, amt);  unlock(&L);
    unlock(&second->m);  unlock(&first->m);
}

void audit(Account *a, Account *b) {   /* caller ensures a->id < b->id */
    lock(&L);
    lock(&a->m);  log_balance(a);  unlock(&a->m);
    lock(&b->m);  log_balance(b);  unlock(&b->m);
    unlock(&L);
}

void sweep(Account *a) {
    lock(&a->m);
    if (a->bal < 0) { lock(&L); log_overdraft(a); unlock(&L); }
    unlock(&a->m);
}
```

